	'kd223cbd7' => 'Lait d’avoine',
	'kd251e6bb' => 'Qui fait quoi, et quand : notre routine quotidienne',
	'kd42d1f4a' => 'Alto Sereno donne un chocolat équilibré et résonnant, aux notes d’abricot sec et de noix grillée.',
	'kd4acb7d8' => 'La table du jeudi',
	'kd5141915' => 'Ridgeway Estate',
	'kd817abcb' => 'Glace les gâteaux de demain en chambre fraîche.',
